// Agent permission profiles staged from the dashboard (Policy → Agent
// permission profiles), served by policy-management.
//
// The control plane validates profile documents with the engine's own schema
// (agent-profile-schema.ts, a generated byte-parity copy of
// packages/core/src/agent-profile-schema.ts) and stores them as versioned,
// audited, optionally four-eyes approved revisions. It does NOT sign or
// deliver them: connectors only trust the Ed25519 tenant detector bundle
// verified against the operator's licensing keys, so the operator publishes a
// staged revision with scripts/provision-agent-profiles.mjs, which pulls it
// through `read_agent_profile_revision` (see
// supabase/migrations/20260928000002_agent_profile_staging.sql for why).

import type { SupabaseClient } from "npm:@supabase/supabase-js@2.116.0";
import { parseDocument } from "npm:yaml@2.8.3";
import { validateAgentProfileDocument } from "./agent-profile-schema.ts";
import { corsJson } from "./cors.ts";
import { isFourEyesRefusal, readPolicyFourEyes, submitPolicyChange } from "./policy-change-control.ts";

const AGENT_PROFILE_ACTIONS = [
	"validate_agent_profiles",
	"read_agent_profiles",
	"agent_profile_history",
	"read_agent_profile_revision",
	"stage_agent_profiles",
	"restore_agent_profiles",
] as const;
export type AgentProfileAction = (typeof AGENT_PROFILE_ACTIONS)[number];

export function isAgentProfileAction(action: string): action is AgentProfileAction {
	return (AGENT_PROFILE_ACTIONS as readonly string[]).includes(action);
}

/** Staged documents are bounded well below the policy-management body limit. */
const MAX_PROFILE_SOURCE_BYTES = 60 * 1024;
const AGENT_PROFILE_HISTORY_PAGE = 50;

/** What the dashboard is told about delivery: staged is not enforced. */
const PROFILE_DELIVERY = {
	delivered: false,
	delivery_status: "staged_not_signed",
	delivery_detail:
		"Staged profiles are not enforced until an operator signs the staged revision into the tenant detector bundle with scripts/provision-agent-profiles.mjs.",
} as const;

type Context = { tenant: string; userId: string; role: string; token: string };
type Row = Record<string, unknown>;

function isRecord(value: unknown): value is Row {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function positiveVersion(value: unknown): value is number {
	return Number.isSafeInteger(value) && Number(value) >= 1 && Number(value) < Number.MAX_SAFE_INTEGER;
}

function versionPrecondition(value: unknown): value is number {
	return Number.isSafeInteger(value) && Number(value) >= 0 && Number(value) < Number.MAX_SAFE_INTEGER;
}

type ProfileSourceResult =
	| { ok: true; document: Row; diagnostics: unknown[]; profiles: string[] }
	| { ok: false; errors: string[] };

/**
 * Parse JSON or YAML profile text exactly like the engine
 * (parseAgentProfileSource: no aliases, no duplicate keys, bounded size) and
 * validate it with the engine schema. Errors name locations, never values.
 */
function validateProfileSource(source: unknown): ProfileSourceResult {
	if (typeof source !== "string" || source.trim() === "") return { ok: false, errors: ["document is empty"] };
	if (new TextEncoder().encode(source).byteLength > MAX_PROFILE_SOURCE_BYTES) {
		return { ok: false, errors: ["document exceeds the 60 KiB staging limit"] };
	}
	let value: unknown;
	try {
		value = JSON.parse(source);
	} catch {
		const parsed = parseDocument(source, { schema: "core", uniqueKeys: true, prettyErrors: false });
		if (parsed.errors.length > 0) return { ok: false, errors: ["document is neither valid JSON nor YAML"] };
		try {
			value = parsed.toJS({ maxAliasCount: 0 });
		} catch {
			return { ok: false, errors: ["document uses YAML aliases, which are not supported"] };
		}
	}
	return validateProfileDocument(value);
}

function validateProfileDocument(value: unknown): ProfileSourceResult {
	const result = validateAgentProfileDocument(value);
	if (!result.ok) return { ok: false, errors: result.errors };
	return {
		ok: true,
		document: result.document as unknown as Row,
		diagnostics: result.diagnostics,
		profiles: result.document.profiles.map((profile) => profile.name),
	};
}

function revisionRow(value: unknown) {
	if (!isRecord(value) || !positiveVersion(value.version) || !isRecord(value.policy) ||
		typeof value.policy_sha256 !== "string" || !/^[0-9a-f]{64}$/.test(value.policy_sha256) ||
		!Number.isSafeInteger(value.profile_count) ||
		typeof value.created_at !== "string" || !Number.isFinite(Date.parse(value.created_at))) {
		return null;
	}
	return {
		version: value.version,
		policy: value.policy,
		policy_sha256: value.policy_sha256,
		profile_count: value.profile_count as number,
		restored_from: positiveVersion(value.restored_from) ? value.restored_from : null,
		updated_by: typeof value.updated_by === "string" ? value.updated_by : null,
		created_at: value.created_at,
	};
}

const REVISION_COLUMNS = "version,policy,policy_sha256,profile_count,restored_from,updated_by,created_at";

async function currentVersion(db: SupabaseClient, tenant: string): Promise<number | null> {
	const { data, error } = await db.from("tenant_agent_profiles").select("version").eq("tenant_id", tenant).maybeSingle();
	if (error || data === undefined) return null;
	if (data === null) return 0;
	return positiveVersion((data as Row).version) ? Number((data as Row).version) : null;
}

async function stageDocument(
	req: Request,
	db: SupabaseClient,
	context: Context,
	expected: number,
	validated: Extract<ProfileSourceResult, { ok: true }>,
	restoredFrom: number | null,
): Promise<Response> {
	const { tenant, userId } = context;
	const fourEyes = await readPolicyFourEyes(db, tenant);
	if (!fourEyes.ok) return corsJson(req, 503, { error: "agent_profiles_unavailable" });
	if (fourEyes.enabled) {
		return await submitPolicyChange(req, db, {
			tenantId: tenant,
			userId,
			kind: "agent_profiles_stage",
			baseVersion: expected,
			payload: restoredFrom === null
				? { policy: validated.document }
				: { policy: validated.document, restored_from: restoredFrom },
		});
	}
	const { data, error } = await db.rpc("stage_agent_profiles", {
		p_tenant_id: tenant,
		p_user_id: userId,
		p_expected_version: expected,
		p_policy: validated.document,
		p_restored_from: restoredFrom,
	});
	if (error) {
		if (isFourEyesRefusal(error)) return corsJson(req, 409, { error: "policy_four_eyes_required" });
		return corsJson(req, error.code === "PT409" ? 409 : error.code === "42501" ? 403 : error.code === "22023" ? 400 : 503, {
			error: error.code === "PT409" ? "policy_version_conflict" : "agent_profiles_stage_failed",
		});
	}
	const row = data as Row | null;
	if (!row || row.version !== expected + 1 || typeof row.policy_sha256 !== "string" ||
		!/^[0-9a-f]{64}$/.test(row.policy_sha256) || typeof row.updated_at !== "string") {
		return corsJson(req, 503, { error: "agent_profiles_stage_failed" });
	}
	return corsJson(req, 200, {
		ok: true,
		staged: true,
		version: row.version,
		policy: row.policy,
		policy_sha256: row.policy_sha256,
		profiles: validated.profiles,
		diagnostics: validated.diagnostics,
		updated_at: row.updated_at,
		...(restoredFrom === null ? {} : { restored_from: restoredFrom }),
		...PROFILE_DELIVERY,
	});
}

/** Called only after verified identity, live tenant membership/status and quota checks. */
export async function handleAgentProfileAction(
	req: Request,
	db: SupabaseClient,
	body: Row,
	context: Context,
): Promise<Response> {
	const { tenant, role, token } = context;
	const action = String(body.action);

	if (action === "validate_agent_profiles") {
		// Pure validation: nothing is read or stored, so no step-up is needed.
		const result = validateProfileSource(body.source);
		return corsJson(req, 200, result.ok
			? { ok: true, valid: true, document: result.document, profiles: result.profiles, diagnostics: result.diagnostics }
			: { ok: true, valid: false, errors: result.errors });
	}

	const writing = action === "stage_agent_profiles" || action === "restore_agent_profiles";
	if (writing && !["owner", "admin"].includes(role)) return corsJson(req, 403, { error: "policy_forbidden" });
	// Profiles describe the tenant's allowed commands, paths and hosts: step-up
	// for reads and writes, like DLP policy.
	const { data: assurance, error: assuranceError } = await db.auth.mfa.getAuthenticatorAssuranceLevel(token);
	if (assuranceError || !assurance) return corsJson(req, 503, { error: "assurance_unavailable" });
	if (assurance.currentLevel !== "aal2") return corsJson(req, 403, { error: "mfa_required" });

	if (action === "read_agent_profiles") {
		const { data, error } = await db.from("tenant_agent_profiles")
			.select("version,policy,policy_sha256,profile_count,updated_by,updated_at").eq("tenant_id", tenant).maybeSingle();
		if (error || data === undefined) return corsJson(req, 503, { error: "agent_profiles_unavailable" });
		const row = data as Row | null;
		if (row && (!positiveVersion(row.version) || !isRecord(row.policy) || typeof row.policy_sha256 !== "string" ||
			typeof row.updated_at !== "string")) {
			return corsJson(req, 503, { error: "agent_profiles_unavailable" });
		}
		return corsJson(req, 200, {
			ok: true,
			staged: row !== null,
			version: row?.version ?? 0,
			policy: row?.policy ?? null,
			policy_sha256: row?.policy_sha256 ?? null,
			profile_count: row?.profile_count ?? 0,
			updated_by: row?.updated_by ?? null,
			updated_at: row?.updated_at ?? null,
			...PROFILE_DELIVERY,
		});
	}

	if (action === "agent_profile_history") {
		if (body.before_version !== undefined && !positiveVersion(body.before_version)) {
			return corsJson(req, 400, { error: "invalid_version" });
		}
		let query = db.from("agent_profile_revisions").select(REVISION_COLUMNS).eq("tenant_id", tenant);
		if (body.before_version !== undefined) query = query.lt("version", Number(body.before_version));
		const { data, error } = await query.order("version", { ascending: false }).limit(AGENT_PROFILE_HISTORY_PAGE + 1);
		if (error || !Array.isArray(data)) return corsJson(req, 503, { error: "agent_profile_history_unavailable" });
		const rows = data.slice(0, AGENT_PROFILE_HISTORY_PAGE).map(revisionRow);
		if (rows.some((row) => row === null)) return corsJson(req, 503, { error: "agent_profile_history_unavailable" });
		const revisions = (rows as NonNullable<ReturnType<typeof revisionRow>>[]).map(({ policy: _policy, ...meta }) => meta);
		return corsJson(req, 200, {
			ok: true,
			revisions,
			next_before_version: data.length > AGENT_PROFILE_HISTORY_PAGE ? revisions[revisions.length - 1].version : null,
		});
	}

	if (action === "read_agent_profile_revision") {
		if (!positiveVersion(body.version)) return corsJson(req, 400, { error: "invalid_version" });
		const [revision, current] = await Promise.all([
			db.from("agent_profile_revisions").select(REVISION_COLUMNS)
				.eq("tenant_id", tenant).eq("version", Number(body.version)).maybeSingle(),
			currentVersion(db, tenant),
		]);
		if (revision.error || revision.data === undefined || current === null) {
			return corsJson(req, 503, { error: "agent_profile_history_unavailable" });
		}
		if (revision.data === null) return corsJson(req, 404, { error: "revision_not_found" });
		const row = revisionRow(revision.data);
		if (!row) return corsJson(req, 503, { error: "agent_profile_history_unavailable" });
		return corsJson(req, 200, {
			ok: true,
			tenant_id: tenant,
			current: row.version === current,
			current_version: current,
			revision: row,
			...PROFILE_DELIVERY,
		});
	}

	const expected = body.expected_version;
	if (!versionPrecondition(expected)) return corsJson(req, 400, { error: "invalid_version" });

	if (action === "restore_agent_profiles") {
		if (!positiveVersion(body.version)) return corsJson(req, 400, { error: "invalid_version" });
		if (Number(body.version) >= Number(expected)) return corsJson(req, 400, { error: "restore_target_not_older" });
		const { data, error } = await db.from("agent_profile_revisions").select(REVISION_COLUMNS)
			.eq("tenant_id", tenant).eq("version", Number(body.version)).maybeSingle();
		if (error || data === undefined) return corsJson(req, 503, { error: "agent_profile_history_unavailable" });
		if (data === null) return corsJson(req, 404, { error: "revision_not_found" });
		const row = revisionRow(data);
		if (!row) return corsJson(req, 503, { error: "agent_profile_history_unavailable" });
		// Re-validate with today's schema; the stored document is restored verbatim.
		const validated = validateProfileDocument(row.policy);
		if (!validated.ok) return corsJson(req, 400, { error: "invalid_agent_profiles", errors: validated.errors });
		return await stageDocument(req, db, context, Number(expected),
			{ ...validated, document: row.policy }, row.version);
	}

	if (action === "stage_agent_profiles") {
		const validated = validateProfileSource(body.source);
		if (!validated.ok) return corsJson(req, 400, { error: "invalid_agent_profiles", errors: validated.errors });
		return await stageDocument(req, db, context, Number(expected), validated, null);
	}

	return corsJson(req, 400, { error: "invalid_action" });
}
